-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeVoter.json. Do not edit: change the chain file or ABI and regenerate.
-- GaugeCreated(address,address,address,address,address,address,address,address)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_voter__gauge_created',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as pool_factory,
    concat('0x', substring(substring(topic2, 3, 64), 25, 40)) as voting_rewards_factory,
    concat('0x', substring(substring(topic3, 3, 64), 25, 40)) as gauge_factory,
    concat('0x', substring(substring(data, 3, 64), 25, 40)) as pool,
    concat('0x', substring(substring(data, 67, 64), 25, 40)) as bribe_voting_reward,
    concat('0x', substring(substring(data, 131, 64), 25, 40)) as fee_voting_reward,
    concat('0x', substring(substring(data, 195, 64), 25, 40)) as gauge,
    concat('0x', substring(substring(data, 259, 64), 25, 40)) as creator
from {{ source('chain_base', 'logs') }}
where topic0 = '0xef9f7d1ffff3b249c6b9bf2528499e935f7d96bb6d6ec4e7da504d1d3c6279e1'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_voter')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
